static void require(bool ok,const char*why){if(!ok)throw std::runtime_error(why);}
class Linear final:public ceres::SizedCostFunction<1,1>{double rhs_;public:explicit Linear(double rhs=0.):rhs_(rhs){}bool Evaluate(double const*const*p,double*r,double**j)const override{r[0]=p[0][0]-rhs_;if(j&&j[0])j[0][0]=1.;return std::isfinite(r[0]);}};
class InactiveADProbe final:public ceres::SizedCostFunction<1,1>,public PHRADValueProbe{public:bool Evaluate(double const*const*,double*r,double**j)const override{r[0]=-1.;return !j||!j[0];}bool EvaluateADValue(double const*const*,double*r)const override{r[0]=-1.;return true;}};
static Json policy(){return {{"schema","rinkfit.engineering_global_phr_policy.v1"},{"initialization","explicit_new_objective_zero_duals"},{"initial_rho",10.},{"rho_growth",2.},{"required_progress_ratio",.5},{"primal_tolerance",1e-9},{"complementarity_tolerance",1e-9}};}
static BuildInventory original(ceres::Problem&p,double*x,double*y){BuildInventory inv;inv.inequality_blocks.push_back(add_phr_inequality(p,std::make_unique<Linear>(),{x},0.,10.,true));inv.equality_blocks.push_back(add_phr_equality(p,std::make_unique<Linear>(),{y},0.,10.));inv.statistical_blocks.push_back(p.AddResidualBlock(new Linear(3.),nullptr,x));return inv;}
static BuildInventory direct(JointPhysicalFeasibilityV1&adapter,ceres::Problem&p,double*x,double*y){BuildInventory inv;inv.statistical_blocks.push_back(p.AddResidualBlock(new Linear(3.),nullptr,x));inv.inequality_blocks.push_back(adapter.add_original_final_factor(p,"physical/original_inequality",false,std::make_unique<Linear>(),{x}));inv.equality_blocks.push_back(adapter.add_original_final_factor(p,"physical_relation/original_equality",true,std::make_unique<Linear>(),{y}));adapter.finish_direct_build(1,1);return inv;}
static void compare_complete_graph(ceres::Problem&a,const BuildInventory&ai,ceres::Problem&b,const BuildInventory&bi,double*x,double*y){ceres::Problem::EvaluateOptions ao,bo;ao.parameter_blocks=bo.parameter_blocks={x,y};ao.residual_blocks={static_cast<ceres::ResidualBlockId>(ai.statistical_blocks.at(0)),static_cast<ceres::ResidualBlockId>(ai.inequality_blocks.at(0)),static_cast<ceres::ResidualBlockId>(ai.equality_blocks.at(0))};bo.residual_blocks={static_cast<ceres::ResidualBlockId>(bi.statistical_blocks.at(0)),static_cast<ceres::ResidualBlockId>(bi.inequality_blocks.at(0)),static_cast<ceres::ResidualBlockId>(bi.equality_blocks.at(0))};double ac=0,bc=0;std::vector<double>ar,br,ag,bg;ceres::CRSMatrix aj,bj;require(a.Evaluate(ao,&ac,&ar,&ag,&aj)&&b.Evaluate(bo,&bc,&br,&bg,&bj),"complete graph comparison failed");require(ac==bc&&ar==br&&ag==bg&&aj.num_rows==bj.num_rows&&aj.num_cols==bj.num_cols&&aj.rows==bj.rows&&aj.cols==bj.cols&&aj.values==bj.values,"direct final PHR changed ordered complete cost/residual/Jacobian");}
