 require(inv.statistical_blocks[0]==original_pixel&&inv.inequality_blocks[0]==original_g&&inv.equality_blocks[0]==original_h,"outer update changed original residual IDs");Json resumed=Json::parse(saved.dump());ceres::Problem other;JointPhysicalFeasibilityV1 restored(resumed,policy(),"same_source");auto other_inv=direct(restored,other,&x,&y);require(resumed==saved,"resume silently reset global PHR dual/progress");compare_complete_graph(problem,inv,other,other_inv,&x,&y);ceres::Problem updated_baseline;BuildInventory updated_inv;updated_inv.statistical_blocks.push_back(updated_baseline.AddResidualBlock(new Linear(3.),nullptr,&x));updated_inv.inequality_blocks.push_back(add_phr_inequality(updated_baseline,std::make_unique<Linear>(),{&x},saved.at("lambda")[0],saved.at("rho"),true));updated_inv.equality_blocks.push_back(add_phr_equality(updated_baseline,std::make_unique<Linear>(),{&y},saved.at("nu")[0],saved.at("rho")));compare_complete_graph(problem,inv,updated_baseline,updated_inv,&x,&y);auto bad=saved;bad["inequality_ids"][0]="wrong_source_constraint";bool rejected=false;try{ceres::Problem invalid;JointPhysicalFeasibilityV1 wrong(bad,policy(),"same_source");direct(wrong,invalid,&x,&y);}catch(const std::runtime_error&){rejected=true;}require(rejected,"changed original constraint identity accepted");
